WITH cleaned AS (SELECT id, customer_id, account_type, opened_date, status, CASE WHEN account_type = 'SAVINGS' THEN 1 ELSE 0 END AS is_savings, COALESCE(status, 'N/A') AS status_filled FROM accounts WHERE customer_id IS NOT NULL), scored AS (SELECT *, MAX(is_savings) OVER (PARTITION BY status ORDER BY opened_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_max_is_savings, COUNT(is_savings) OVER (PARTITION BY status ORDER BY opened_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_count_is_savings, MIN(is_savings) OVER (PARTITION BY status ORDER BY opened_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_min_is_savings, AVG(is_savings) OVER (PARTITION BY status ORDER BY opened_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_avg_is_savings, AVG(is_savings) OVER (PARTITION BY status ORDER BY is_savings, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS is_savings_avg_3 FROM cleaned), eligible AS (SELECT s.* FROM scored s WHERE NOT EXISTS (SELECT 1 FROM transactions ch WHERE ch.account_id = s.id AND ch.txn_time <= s.opened_date)), latest_match AS (SELECT s.id, s.account_type, s.status, s.last7_max_is_savings, s.last7_count_is_savings, latest.merchant FROM eligible s JOIN LATERAL (SELECT c.merchant FROM transactions c WHERE c.account_id = s.id AND c.txn_time <= s.opened_date ORDER BY c.txn_time DESC, c.id DESC LIMIT 1) latest ON TRUE), with_last AS (SELECT s.*, latest.transaction_merchant FROM latest_match s JOIN LATERAL (SELECT c.merchant AS transaction_merchant FROM transactions c WHERE c.account_id = s.id ORDER BY c.txn_time DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT status, MAX(last7_max_is_savings) FILTER (WHERE transaction_merchant = '7-Eleven') AS 7_eleven_max_last7_max_is_savings, SUM(CASE WHEN status = 'OPEN' THEN last7_max_is_savings ELSE 0 END) AS open_last7_max_is_savings, ROUND(AVG(last7_max_is_savings), 2) AS avg_last7_max_is_savings, COUNT(*) FILTER (WHERE account_type = 'LOAN') AS loan_rows, SUM(last7_count_is_savings) AS total_last7_count_is_savings, SIZE(COLLECT_SET(transaction_merchant)) AS num_transaction_merchants FROM with_last GROUP BY status
